import{_ as p,a0 as o,w as e,s as a,I as i,x as t,a1 as s,A as l,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"Linux Mint 的發行週期 | LCTT x X-CMD","titleTemplate":false,"description":"Linux Mint 的發行週期 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux Mint 的發行週期 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux Mint 的發行週期 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20220825 Linux Mint Release Cycle- What You Need to Know","title":"Linux Mint 的發行週期","tag":"202304","desc":""},"relativePath":"202304/20220825 Linux Mint Release Cycle- What You Need to Know.md","filePath":"[post].md"}'),x={name:"202304/20220825 Linux Mint Release Cycle- What You Need to Know.md"};function M(L,n,d,m,b,g){const u=o("Link");return e(),a("div",null,[n[27]||(n[27]=i("h1",{id:"linux-mint-的發行週期",tabindex:"-1"},[t("Linux Mint 的發行週期 "),i("a",{class:"header-anchor",href:"#linux-mint-的發行週期","aria-label":"Permalink to “Linux Mint 的發行週期”"},"​")],-1)),n[28]||(n[28]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202304/24/231022h7rzqz8zfvviaqb7.jpg",alt:""})],-1)),n[29]||(n[29]=i("p",null,"你可能知道，Linux Mint 是一個基於 Ubuntu 的發行版。",-1)),n[30]||(n[30]=i("p",null,"Ubuntu 每六個月發佈一個新版本，但 Linux Mint 並不遵循六個月一次的發行模式。",-1)),i("p",null,[n[2]||(n[2]=t("Linux Mint 以 Ubuntu LTS（",-1)),i("ruby",null,[s(u,{href:"https://itsfoss.com/long-term-support-lts/"},{default:l(()=>[...n[0]||(n[0]=[t("長期支持",-1)])]),_:1}),n[1]||(n[1]=i("rt",null,"long term support",-1))]),n[3]||(n[3]=t("）版本作為其基礎。Ubuntu 的 LTS 版本每兩年發佈一次，所以 ",-1)),n[4]||(n[4]=i("strong",null,"你也會每兩年得到一個 Mint 的大版本更新",-1)),n[5]||(n[5]=t("（比如 Mint 19, 20, 21 等）。",-1))]),n[31]||(n[31]=r('<p>與 Ubuntu LTS 版本一樣，Linux Mint 的大版本也被支持五年。雖然在這期間有<strong>三個小更新版本</strong>（比如 Mint 20.1、20.2、20.3）。</p><p>與 Ubuntu 相比，多久能得到一次 Linux Mint 的升級？你應該在什麼時候等待 Linux Mint 的升級？當有新版本的時候，你應該升級到新版本嗎？</p><p>在這裏，讓我重點介紹一下這些 Linux Mint 的發行週期的重要細節。</p><h3 id="linux-mint-的發行週期-1" tabindex="-1">Linux Mint 的發行週期 <a class="header-anchor" href="#linux-mint-的發行週期-1" aria-label="Permalink to “Linux Mint 的發行週期”">​</a></h3><p>Ubuntu 每兩年發佈一個長期支持版本。之後很快就會有一個 Mint 版本出現。換句話説，你每兩年就會得到一個新的 Mint 版本。</p><p>所以，Linux Mint 20 是在 2020 年基於 Ubuntu 20.04 發行的，Mint 21 是在 2022 年基於 Ubuntu 22.04 發行的。</p><p>與 Ubuntu 不同，Mint 沒有嚴格的發行時間表。沒有事先確定的發行日期。新版本在其開發者認為準備好的時候就會到來。</p><h4 id="小版本" tabindex="-1">小版本 <a class="header-anchor" href="#小版本" aria-label="Permalink to “小版本”">​</a></h4><p>在 Mint 的兩個大版本發佈之間，有三個小版本，每隔 6 個月發佈一次。</p><p>即 Mint 20（即 20.0）是在 2020 年 6 月發佈的。Mint 20.1 在 2020 年 12 月，Mint 20.2 在 2021 年 6 月，Mint 20.3 在 2021 年 12 月。在這之後，Mint 團隊將致力於開發下一個大版本。</p><p>這些小版本會更新什麼？比如，一個新版本的桌面環境，主要包含用户圖形界面的視覺變化。它有時也可能提供新的應用程序。</p><p>升級到小版本是可選的。你可以選擇繼續使用 20.1，而不升級到 20.2 和 20.3。這是那些不喜歡頻繁（在圖形界面上）改變他們系統的人的首選。</p><p>在最後一個消版本發佈（XX.03）之後，你的系統將只得到已安裝軟件的安全和維護更新。你不會得到桌面環境和其他一些軟件（如 GIMP 或 LibreOffice）的新的大版本更新。</p><h4 id="支持週期" tabindex="-1">支持週期 <a class="header-anchor" href="#支持週期" aria-label="Permalink to “支持週期”">​</a></h4>',14)),i("p",null,[n[7]||(n[7]=t("並非所有基於 Ubuntu 的發行版都能為你提供與 Canonical 的 Ubuntu 相同的週期性更新優勢。許多基於 Ubuntu 的發行版和 ",-1)),s(u,{href:"https://itsfoss.com/which-ubuntu-install/"},{default:l(()=>[...n[6]||(n[6]=[t("官方的衍生版本",-1)])]),_:1}),n[8]||(n[8]=t(" 提供了最長 3 年的支持。",-1))]),n[32]||(n[32]=r('<p>幸運的是，對於 <strong>Linux Mint</strong> 來説，你可以得到和 Ubuntu 一樣的更新福利。</p><p><strong>每個 Linux Mint 版本的支持期為 5 年</strong>，在此之後，你必須升級到下一個版本，或者重新安裝較新的版本。</p><p>例如，Mint 20 是在 2020 年發佈的，比 Ubuntu 20.04 晚幾個月。Ubuntu 20.04 LTS 被支持到 2025 年，因此 Mint 20 系列也被支持到 2025 年。</p><p>一個系列的所有小版本都支持到同一日期。Mint 20.1、20.2 和 20.3 都將被支持到 2025 年。</p><p>同樣地，Ubuntu 22.04 LTS 將被支持到 2027 年 4 月。你可以期待 Linux Mint 21 系列（它基於 Ubuntu 22.04）的更新週期到相同的時間線。</p><p><strong>總結一下：</strong></p><ul><li>你每兩年得到一個新的 Linux Mint 大版本</li><li>每個大版本的支持週期為 5 年</li><li>每個大版本（XX 版）在下一個大版本之前都會有三個小版本（XX.1、XX.2、XX.3）</li><li>小版本（XX.1，XX.2，XX.3）與大版本（XX）的支持時間相同</li></ul><h3 id="你什麼時候應該升級-linux-mint" tabindex="-1">你什麼時候應該升級 Linux Mint？ <a class="header-anchor" href="#你什麼時候應該升級-linux-mint" aria-label="Permalink to “你什麼時候應該升級 Linux Mint？”">​</a></h3><p>這完全取決於你，</p><p>每兩年會有一個新的大版本。你可以選擇在那時升級它，或者你可以在整個五年的生命週期內保持你目前的版本。</p><p>除非你想獲得最新的功能和改進，你可以選擇不把你的 Linux Mint 安裝升級到另一個大版本。</p><p>對於小版本，你可以選擇更新，也可以不更新。比如，20 到 20.1 或 20.1 到 20.2。即使你不使用最新的小版本，你仍然會得到重要的安全和維護更新。</p>',12)),i("p",null,[n[10]||(n[10]=t("你可以參考我們的 ",-1)),s(u,{href:"https://itsfoss.com/upgrade-linux-mint-version/"},{default:l(()=>[...n[9]||(n[9]=[t("Linux Mint 升級指南",-1)])]),_:1}),n[11]||(n[11]=t(" 以尋求幫助。",-1))]),n[33]||(n[33]=r('<h3 id="linux-mint-的版本劃分和命名" tabindex="-1">Linux Mint 的版本劃分和命名 <a class="header-anchor" href="#linux-mint-的版本劃分和命名" aria-label="Permalink to “Linux Mint 的版本劃分和命名”">​</a></h3><p>與 Ubuntu 發行版不同，Linux Mint 有一個不同的編號方案。Linux Mint 喜歡在每一個 Ubuntu LTS 版本中提升編號。</p><p>換句話説:</p><p>Linux Mint 19 → <strong>Ubuntu 18.04 LTS</strong></p><p>Linux Mint 20 → <strong>Ubuntu 20.04 LTS</strong></p><p>Linux Mint 21 → <strong>Ubuntu 22.04 LTS</strong></p><p>所以，你應該避開以下的混淆：</p><p><em>Linux Mint 20 基於 Ubuntu 20.04 並不意味着 Linux Mint 21 將基於 Ubuntu 21.04。</em></p><p>此外，每個版本都有<strong>三個小版本</strong>，帶有內核的小更新和一些 Linux Mint 應用程序的潛在升級。</p><p>現在，來看看它的<strong>命名方案</strong>：</p><p>每個 Linux Mint 版本，無論是小的還是大的，都有一個代號。通常，它是一個女性的名字，通常源自希臘或拉丁語。</p><p>和 Ubuntu 一樣，代號也有一個模式。大版本的代號是按字母順序遞增的。當涉及到小版本時，你會發現新的名字會以相同的字母開頭。</p><p>例如，Mint 20 被稱為 <strong>Ulyana</strong>，20.1 為 <strong>Ulyssa</strong>，20.2 為 <strong>Uma</strong>，而 20.3 為 <strong>Una</strong>。同樣地，Mint 19 系列的代號以 T 開頭。</p><p>在寫這篇文章的時候，Mint 21（最新版本）的代號以 <strong>V</strong> 開頭，21 系列的第一個版本叫 <strong>Vanessa</strong>。</p><p>在 Mint 21 系列中至少還會有三個小版本，它們將每六個月發佈一次，直到 2024 年的下一個 Mint 大版本。而它們都將有一個以字母 V 開頭的代號。</p><h3 id="薄荷留香" tabindex="-1">薄荷留香 <a class="header-anchor" href="#薄荷留香" aria-label="Permalink to “薄荷留香”">​</a></h3><p>我希望這篇文章能消除對 Linux Mint 升級的各種困惑，並讓你更多地瞭解 Linux Mint 的發佈和更新週期。</p><p><em>（題圖：MJ/mint cinamon plain dark background in high resolution, very detailed, 8k）</em></p><hr>',19)),i("p",null,[n[13]||(n[13]=t("via: ",-1)),s(u,{href:"https://itsfoss.com/linux-mint-release-cycle/"},{default:l(()=>[...n[12]||(n[12]=[t("https://itsfoss.com/linux-mint-release-cycle/",-1)])]),_:1})]),i("p",null,[n[18]||(n[18]=t("作者：",-1)),s(u,{href:"https://itsfoss.com/author/ankush/"},{default:l(()=>[...n[14]||(n[14]=[t("Ankush Das",-1)])]),_:1}),n[19]||(n[19]=t(" 選題：",-1)),s(u,{href:"https://github.com/lkxed"},{default:l(()=>[...n[15]||(n[15]=[t("lkxed",-1)])]),_:1}),n[20]||(n[20]=t(" 譯者：",-1)),s(u,{href:"https://github.com/chris000132"},{default:l(()=>[...n[16]||(n[16]=[t("chris000132",-1)])]),_:1}),n[21]||(n[21]=t(" 校對：",-1)),s(u,{href:"https://github.com/wxy"},{default:l(()=>[...n[17]||(n[17]=[t("wxy",-1)])]),_:1})]),i("p",null,[n[24]||(n[24]=t("本文由 ",-1)),s(u,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...n[22]||(n[22]=[t("LCTT",-1)])]),_:1}),n[25]||(n[25]=t(" 原創編譯，",-1)),s(u,{href:"https://linux.cn/"},{default:l(()=>[...n[23]||(n[23]=[t("Linux中國",-1)])]),_:1}),n[26]||(n[26]=t(" 榮譽推出",-1))])])}const C=p(x,[["render",M]]);export{U as __pageData,C as default};
